import java.util.*;

public class Main {
    static int r, c;
    static char[][] g;
    static long[][] memo;
    static final long MOD = 1_000_000_007L;

    static long paths(int i, int j) {
        if (i >= r || j >= c || g[i][j] == '#') return 0;
        if (i == r - 1 && j == c - 1) return 1;
        if (memo[i][j] != -1) return memo[i][j];
        return memo[i][j] = (paths(i + 1, j) + paths(i, j + 1)) % MOD;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        r = in.nextInt();
        c = in.nextInt();
        g = new char[r][];
        for (int i = 0; i < r; i++) g[i] = in.next().toCharArray();
        memo = new long[r][c];
        for (long[] row : memo) Arrays.fill(row, -1);
        System.out.println(paths(0, 0) % MOD);
    }
}

